tool.expression:
{
var cond = $job.input_type;
var op = cond.comparison.operator;
var input = cond.input;
var isNull = input === null || input === undefined;

if (op == "is_null") { return { output: isNull }; }
if (op == "is_not_null") { return { output: !isNull }; }
if (op == "is_empty") { return { output: isNull || input === "" }; }
if (op == "is_not_empty") { return { output: !(isNull || input === "") }; }

if (isNull) {
    if ($job.null_handling == "fail") {
        return { __error_message: "The input value is unset (null). Connect a value, or choose the result for unset inputs." };
    }
    return { output: $job.null_handling == "true" };
}

var value = cond.comparison.value;
if (value === null || value === undefined) {
    return { __error_message: "The value to compare to is unset (null)." };
}
var result;
if (cond.type == "text") {
    var a = String(input);
    var b = String(value);
    if (op == "regex" || op == "not_regex") {
        var re;
        try {
            re = new RegExp(b, cond.ignore_case ? "i" : "");
        } catch (e) {
            return { __error_message: "Invalid regular expression '" + b + "': " + e.message };
        }
        result = re.test(a);
        return { output: op == "regex" ? result : !result };
    }
    if (cond.ignore_case) {
        a = a.toLowerCase();
        b = b.toLowerCase();
    }
    switch (op) {
        case "eq": result = a === b; break;
        case "ne": result = a !== b; break;
        case "contains": result = a.indexOf(b) != -1; break;
        case "not_contains": result = a.indexOf(b) == -1; break;
        case "starts_with": result = a.slice(0, b.length) === b; break;
        case "not_starts_with": result = a.slice(0, b.length) !== b; break;
        case "ends_with": result = a.length >= b.length && a.slice(a.length - b.length) === b; break;
        case "not_ends_with": result = !(a.length >= b.length && a.slice(a.length - b.length) === b); break;
        default: return { __error_message: "Unknown text operator: " + op };
    }
} else {
    switch (op) {
        case "eq": result = input == value; break;
        case "ne": result = input != value; break;
        case "lt": result = input < value; break;
        case "le": result = input <= value; break;
        case "gt": result = input > value; break;
        case "ge": result = input >= value; break;
        default: return { __error_message: "Unknown numeric operator: " + op };
    }
}
return { output: result };
}
